// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;

    function setUp() public { c = new DnGmxBatchingManager(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));

        bool ok;
        bool val;
        try c.paused() returns (bool v) {
            ok = true;
            val = v;
        } catch {
            ok = false;
            val = false;
        }

        assertTrue(ok && val == false);
    }
}
